<?php
namespace App\Services;
use App\Models\Attendance;use Illuminate\Database\Eloquent\Builder;
class AttendanceReportService { public function query(array $f):Builder{$q=Attendance::query()->with(['employee:id,name,employee_code,department_id,office_id','employee.department:id,name','office:id,name']);foreach(['employee_id','status','mode'] as $k)if(isset($f[$k]))$q->where("attendance.$k",$f[$k]);if(isset($f['office_id']))$q->where('attendance.office_id',$f['office_id']);if(isset($f['department_id']))$q->whereHas('employee',fn($x)=>$x->where('department_id',$f['department_id']));if(isset($f['from']))$q->where('attendance_date','>=',$f['from']);if(isset($f['to']))$q->where('attendance_date','<=',$f['to']);if(isset($f['search']))$q->whereHas('employee',fn($x)=>$x->where('name','like','%'.$f['search'].'%')->orWhere('employee_code','like','%'.$f['search'].'%'));return $q->orderBy($f['sort']??'attendance_date',$f['direction']??'desc');} public function row(Attendance $a):array{return ['date'=>$a->attendance_date->toDateString(),'employee'=>$a->employee->name,'employee_code'=>$a->employee->employee_code,'department'=>$a->employee->department?->name,'office'=>$a->office?->name,'mode'=>$a->mode,'status'=>$a->status,'check_in'=>$a->check_in?->toDateTimeString(),'check_out'=>$a->check_out?->toDateTimeString(),'working_minutes'=>$a->working_minutes,'late_minutes'=>$a->late_minutes,'early_departure_minutes'=>$a->early_departure_minutes,'overtime_minutes'=>$a->overtime_minutes];}}
